param(
    [switch]$Publish
)

$ErrorActionPreference = "Stop"
$Version = "0.3.0"
$Tag = "v$Version"

$Project = "C:\Users\wango\Desktop\dota2voice2text"
if (Test-Path (Join-Path (Get-Location) ".git")) {
    $Project = (Get-Location).Path
}

if (-not (Test-Path (Join-Path $Project ".git"))) {
    throw "Не найден Git-репозиторий Dota2voice2text: $Project"
}

function Write-EmbeddedFile {
    param(
        [string]$RelativePath,
        [string]$Base64
    )

    $target = Join-Path $Project $RelativePath
    $parent = Split-Path -Parent $target
    if ($parent) {
        New-Item -ItemType Directory -Force $parent | Out-Null
    }

    [IO.File]::WriteAllBytes(
        $target,
        [Convert]::FromBase64String($Base64)
    )
}

function Ask-YesNo {
    param([string]$Question)

    while ($true) {
        $answer = (Read-Host "$Question [Y/N]").Trim().ToLowerInvariant()
        if ($answer -in @("y", "yes", "д", "да")) { return $true }
        if ($answer -in @("n", "no", "н", "нет")) { return $false }
    }
}

function Stop-AppProcess {
    param($Process)
    if ($null -eq $Process) { return }
    try {
        if (-not $Process.HasExited) {
            Stop-Process -Id $Process.Id -Force -ErrorAction SilentlyContinue
        }
    } catch {}
}

Push-Location $Project
$appProcess = $null

try {
    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Cyan
    Write-Host " Dota2voice2text v0.3.0 - FINAL RELEASE" -ForegroundColor Cyan
    Write-Host "============================================================" -ForegroundColor Cyan
    Write-Host ""

    # ------------------------------------------------------------
    # 1. Apply final release files.
    # ------------------------------------------------------------
    Write-Host "[1/9] Применяю финальные release-файлы..." -ForegroundColor Cyan

    Write-EmbeddedFile -RelativePath '.github/workflows/release.yml' -Base64 @'

'@
    Write-EmbeddedFile -RelativePath 'README.md' -Base64 @'

'@
    Write-EmbeddedFile -RelativePath 'CHANGELOG.md' -Base64 @'

'@
    Write-EmbeddedFile -RelativePath '.gitignore' -Base64 @'

'@

    Write-Host "Release workflow / README / CHANGELOG / .gitignore: OK" -ForegroundColor Green

    # ------------------------------------------------------------
    # 2. Clean only local helper garbage from project root.
    # ------------------------------------------------------------
    Write-Host "[2/9] Чищу временные helper-файлы..." -ForegroundColor Cyan

    $selfName = Split-Path -Leaf $MyInvocation.MyCommand.Path
    $helperPatterns = @(
        "APPLY_V030_*.ps1",
        "INSTALL_V030_*.ps1",
        "REPAIR_*V030*.ps1",
        "FINALIZE_V030*.ps1",
        "FIX_V030_*.ps1",
        "SETUP_V030_*.ps1",
        "EXPORT_V030_SOURCE.ps1",
        "CLEAN_AND_BUILD_V030.ps1"
    )

    foreach ($pattern in $helperPatterns) {
        Get-ChildItem $Project -File -Filter $pattern -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -ne $selfName } |
            Remove-Item -Force -ErrorAction SilentlyContinue
    }

    Get-ChildItem $Project -Directory -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like "_v030_*" } |
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue

    Write-Host "Временный мусор: OK" -ForegroundColor Green

    # ------------------------------------------------------------
    # 3. Verify versions and required files.
    # ------------------------------------------------------------
    Write-Host "[3/9] Проверяю версии и структуру..." -ForegroundColor Cyan

    $versionText = Get-Content ".\src\version.py" -Raw -Encoding UTF8
    if ($versionText -notmatch 'APP_VERSION\s*=\s*["'']0\.3\.0["'']') {
        throw "src/version.py не содержит APP_VERSION = 0.3.0"
    }

    $issText = Get-Content ".\packaging\Dota2voice2text.iss" -Raw -Encoding UTF8
    if ($issText -notmatch '#define\s+MyAppVersion\s+"0\.3\.0"') {
        throw "Dota2voice2text.iss не содержит MyAppVersion 0.3.0"
    }

    $required = @(
        "app.py",
        "README.md",
        "CHANGELOG.md",
        "requirements.txt",
        "src\gui\main_window.py",
        "src\gui\self_test_dialog.py",
        "src\utils\self_test.py",
        "src\utils\health_check.py",
        "src\utils\dota_status.py",
        "src\utils\app_icon.py",
        "src\utils\windows_app.py",
        "assets\icons\app_icon.ico",
        "assets\icons\app_icon.png",
        "scripts\build_windows.ps1",
        "packaging\Dota2voice2text.iss",
        ".github\workflows\release.yml"
    )

    foreach ($file in $required) {
        if (-not (Test-Path $file)) {
            throw "Отсутствует обязательный файл: $file"
        }
    }

    Write-Host "Версия и структура: OK" -ForegroundColor Green

    # ------------------------------------------------------------
    # 4. Python + JSON validation.
    # ------------------------------------------------------------
    Write-Host "[4/9] Проверяю Python и JSON..." -ForegroundColor Cyan

    $Python = Join-Path $Project ".venv313\Scripts\python.exe"
    if (-not (Test-Path $Python)) {
        throw "Не найден .venv313\Scripts\python.exe"
    }

    $pyFiles = Get-ChildItem $Project -Recurse -File -Filter "*.py" |
        Where-Object {
            $_.FullName -notmatch '\\.venv' -and
            $_.FullName -notmatch '\\build\\' -and
            $_.FullName -notmatch '\\dist\\'
        }

    foreach ($file in $pyFiles) {
        & $Python -m py_compile $file.FullName
        if ($LASTEXITCODE -ne 0) {
            throw "py_compile упал: $($file.FullName)"
        }
    }

    @'
import json
from pathlib import Path

for path in Path("data").rglob("*.json"):
    with path.open("r", encoding="utf-8-sig") as f:
        json.load(f)
    print("JSON OK:", path)
'@ | & $Python -

    if ($LASTEXITCODE -ne 0) {
        throw "JSON validation failed."
    }

    Write-Host "Python / JSON: OK" -ForegroundColor Green

    # ------------------------------------------------------------
    # 5. Clean local build.
    # ------------------------------------------------------------
    Write-Host "[5/9] Собираю portable build..." -ForegroundColor Cyan

    Remove-Item ".\build" -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item ".\dist" -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item ".\Dota2voice2text.spec" -Force -ErrorAction SilentlyContinue

    & ".\scripts\build_windows.ps1"
    if ($LASTEXITCODE -ne 0) {
        throw "build_windows.ps1 завершился с ошибкой."
    }

    $DistDir = Join-Path $Project "dist\Dota2voice2text"
    $Exe = Join-Path $DistDir "Dota2voice2text.exe"
    if (-not (Test-Path $Exe)) {
        throw "После сборки не найден EXE: $Exe"
    }

    Write-Host "Portable build: OK" -ForegroundColor Green

    # ------------------------------------------------------------
    # 6. Build local release artifacts.
    # ------------------------------------------------------------
    Write-Host "[6/9] Создаю ZIP / Setup / SHA-256..." -ForegroundColor Cyan

    $ReleaseDir = Join-Path $Project ".release\$Tag"
    Remove-Item $ReleaseDir -Recurse -Force -ErrorAction SilentlyContinue
    New-Item -ItemType Directory -Force $ReleaseDir | Out-Null

    $PortableName = "Dota2voice2text-v$Version-windows-x64.zip"
    $PortableZip = Join-Path $ReleaseDir $PortableName

    Compress-Archive `
        -Path "$DistDir\*" `
        -DestinationPath $PortableZip `
        -CompressionLevel Optimal `
        -Force

    $portableHash = (Get-FileHash $PortableZip -Algorithm SHA256).Hash.ToLowerInvariant()
    "$portableHash  $PortableName" |
        Set-Content "$PortableZip.sha256" -Encoding ASCII

    $InstallerDir = Join-Path $Project "installer"
    $Payload = Join-Path $InstallerDir "payload"
    Remove-Item $InstallerDir -Recurse -Force -ErrorAction SilentlyContinue
    New-Item -ItemType Directory -Force $Payload | Out-Null
    Copy-Item "$DistDir\*" $Payload -Recurse -Force
    Copy-Item ".\packaging\Dota2voice2text.iss" "$InstallerDir\Dota2voice2text.iss" -Force

    $isccCandidates = @(
        "$env:LOCALAPPDATA\Programs\Inno Setup 6\ISCC.exe",
        "${env:ProgramFiles(x86)}\Inno Setup 6\ISCC.exe",
        "$env:ProgramFiles\Inno Setup 6\ISCC.exe"
    )

    $ISCC = $isccCandidates |
        Where-Object { Test-Path $_ } |
        Select-Object -First 1

    if (-not $ISCC) {
        throw "ISCC.exe не найден. Установи Inno Setup 6."
    }

    Push-Location $InstallerDir
    try {
        & $ISCC ".\Dota2voice2text.iss"
        if ($LASTEXITCODE -ne 0) {
            throw "Inno Setup завершился с ошибкой."
        }
    }
    finally {
        Pop-Location
    }

    $SetupSource = Join-Path $InstallerDir "output\Dota2voice2text-v$Version-Setup.exe"
    if (-not (Test-Path $SetupSource)) {
        throw "Не найден Setup.exe: $SetupSource"
    }

    $SetupName = "Dota2voice2text-v$Version-Setup.exe"
    $SetupTarget = Join-Path $ReleaseDir $SetupName
    Copy-Item $SetupSource $SetupTarget -Force

    $setupHash = (Get-FileHash $SetupTarget -Algorithm SHA256).Hash.ToLowerInvariant()
    "$setupHash  $SetupName" |
        Set-Content "$SetupTarget.sha256" -Encoding ASCII

    Write-Host "Локальные release artifacts: OK" -ForegroundColor Green
    Write-Host ""
    Write-Host "  $PortableZip" -ForegroundColor DarkGray
    Write-Host "  $SetupTarget" -ForegroundColor DarkGray

    # ------------------------------------------------------------
    # 7. Launch built EXE for final manual smoke test.
    # ------------------------------------------------------------
    Write-Host "[7/9] Финальный smoke-test..." -ForegroundColor Cyan
    Write-Host "Сейчас откроется СОБРАННЫЙ EXE." -ForegroundColor Yellow
    Write-Host "Проверь: интерфейс, Самотест, иконку, микрофон, запуск/остановку." -ForegroundColor Yellow

    $appProcess = Start-Process -FilePath $Exe -WorkingDirectory $DistDir -PassThru
    Start-Sleep -Seconds 2

    $works = Ask-YesNo "Финальная сборка работает нормально?"
    Stop-AppProcess $appProcess
    $appProcess = $null

    if (-not $works) {
        Write-Host ""
        Write-Host "Релиз НЕ опубликован. Локальные artifacts сохранены в:" -ForegroundColor Yellow
        Write-Host $ReleaseDir
        exit 2
    }

    Write-Host "Smoke-test: OK" -ForegroundColor Green

    # ------------------------------------------------------------
    # 8. Prepare git commit.
    # ------------------------------------------------------------
    Write-Host "[8/9] Подготавливаю Git..." -ForegroundColor Cyan

    $origin = (git remote get-url origin).Trim()
    Write-Host "Origin: $origin" -ForegroundColor DarkGray

    git add -A
    if ($LASTEXITCODE -ne 0) {
        throw "git add завершился с ошибкой."
    }

    Write-Host ""
    Write-Host "Staged changes:" -ForegroundColor Cyan
    git diff --cached --stat
    Write-Host ""

    if (-not $Publish) {
        $Publish = Ask-YesNo "Опубликовать v0.3.0 на GitHub сейчас?"
    }

    if (-not $Publish) {
        Write-Host ""
        Write-Host "Сборка готова, но тег не создан и релиз не опубликован." -ForegroundColor Yellow
        Write-Host "Когда будешь готов — снова запусти этот скрипт с -Publish." -ForegroundColor Yellow
        Write-Host "Локальные artifacts: $ReleaseDir" -ForegroundColor Cyan
        exit 0
    }

    # ------------------------------------------------------------
    # 9. Commit / push / tag. GitHub Actions creates public release.
    # ------------------------------------------------------------
    Write-Host "[9/9] Публикую $Tag..." -ForegroundColor Cyan

    if (-not (Get-Command gh -ErrorAction SilentlyContinue)) {
        throw "GitHub CLI (gh) не найден."
    }

    gh auth status
    if ($LASTEXITCODE -ne 0) {
        throw "GitHub CLI не авторизован."
    }

    $existingLocalTag = git tag -l $Tag
    if ($existingLocalTag) {
        throw "Локальный тег $Tag уже существует."
    }

    $existingRemoteTag = git ls-remote --tags origin "refs/tags/$Tag"
    if ($existingRemoteTag) {
        throw "Тег $Tag уже существует на origin."
    }

    $stagedFiles = git diff --cached --name-only
    if ($stagedFiles) {
        git commit -m "Release $Tag"
        if ($LASTEXITCODE -ne 0) {
            throw "git commit завершился с ошибкой."
        }
    }
    else {
        Write-Host "Новых изменений для commit нет; использую текущий HEAD." -ForegroundColor Yellow
    }

    git push
    if ($LASTEXITCODE -ne 0) {
        throw "git push завершился с ошибкой."
    }

    git tag -a $Tag -m "Dota2voice2text $Tag"
    if ($LASTEXITCODE -ne 0) {
        throw "Не удалось создать тег $Tag."
    }

    git push origin $Tag
    if ($LASTEXITCODE -ne 0) {
        throw "Не удалось отправить тег $Tag."
    }

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " v0.3.0 ОТПРАВЛЕН В GITHUB ACTIONS" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "GitHub Actions теперь автоматически соберёт:" -ForegroundColor Cyan
    Write-Host " - Portable ZIP"
    Write-Host " - Setup.exe"
    Write-Host " - SHA-256"
    Write-Host " - GitHub Release $Tag"
    Write-Host ""

    Start-Sleep -Seconds 4
    gh run list --workflow "Windows Release" --limit 5
    Write-Host ""
    Write-Host "Локальные проверенные artifacts лежат здесь:" -ForegroundColor Cyan
    Write-Host $ReleaseDir
}
finally {
    Stop-AppProcess $appProcess
    Pop-Location
}
